package msfasp

import "github.com/TheManticoreProject/Manticore/network/dcerpc/ndr"

// FW_AUTH_SUITE ([MS-FASP]). Generated by tools/idlgen; verify pointer/array tags.
type FW_AUTH_SUITE struct {
	Method FW_AUTH_METHOD
	WFlags uint16
	Field  FW_AUTH_SUITE_Field
}

// FW_AUTH_SUITE_Field is the Method-discriminated union of FW_AUTH_SUITE
// ([MS-FASP] 2.2.53): certificate methods (MACHINE_CERT=5, USER_CERT=7) carry a CA
// name and optional criteria; MACHINE_SHKEY=3 carries a shared key; Kerberos methods
// (MACHINE_KERB=2, USER_KERB=6) carry an optional proxy server; other methods select
// the empty ([default]) arm.
type FW_AUTH_SUITE_Field struct {
	Tag          FW_AUTH_METHOD      `ndr:"switch,enum"`
	MachineCert  FW_AUTH_SUITE_CERT  `ndr:"case=5"`
	UserCert     FW_AUTH_SUITE_CERT  `ndr:"case=7"`
	MachineShkey FW_AUTH_SUITE_SHKEY `ndr:"case=3"`
	MachineKerb  FW_AUTH_SUITE_KERB  `ndr:"case=2"`
	UserKerb     FW_AUTH_SUITE_KERB  `ndr:"case=6"`
}

// FW_AUTH_SUITE_CERT is the certificate arm of FW_AUTH_SUITE_Field ([MS-FASP] 2.2.53).
type FW_AUTH_SUITE_CERT struct {
	WszCAName     *ndr.WSTR         `ndr:"ref"`
	PCertCriteria *FW_CERT_CRITERIA `ndr:"unique"`
}

// FW_AUTH_SUITE_SHKEY is the pre-shared-key arm of FW_AUTH_SUITE_Field ([MS-FASP] 2.2.53).
type FW_AUTH_SUITE_SHKEY struct {
	WszSHKey *ndr.WSTR `ndr:"ref"`
}

// FW_AUTH_SUITE_KERB is the Kerberos arm of FW_AUTH_SUITE_Field ([MS-FASP] 2.2.53).
type FW_AUTH_SUITE_KERB struct {
	WszProxyServer *ndr.WSTR `ndr:"unique"`
}
